    s = (s or "").strip()
    if s.startswith("(") and s.endswith(")"):
        s = s[1:-1]
    parts, buf, depth, q, esc = [], [], 0, "", False
    for ch in s:
        if q:
            buf.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == q:
                q = ""
        elif ch in "\"'":
            q = ch; buf.append(ch)
        elif ch in "([{":
            depth += 1; buf.append(ch)
        elif ch in ")]}":
            depth -= 1; buf.append(ch)
        elif ch == "," and depth == 0:
            parts.append("".join(buf).strip()); buf = []
        else:
            buf.append(ch)
    if buf:
        parts.append("".join(buf).strip())
    return [p for p in parts if p]


